/*
 *  Transfer money from inventory to monster when paying
 *  shopkeepers, priests, oracle, succubus, and other demons.
 *  Simple with only gold coins.
 *  This routine will handle money changing when multiple
 *  coin types is implemented, only appropriate
 *  monsters will pay change.  (Peaceful shopkeepers, priests
 *  and the oracle try to maintain goodwill while selling
 *  their wares or services.  Angry monsters and all demons
 *  will keep anything they get their hands on.
 *  Returns the amount actually paid, so we can know
 *  if the monster kept the change.
 */
/**
 * @param {$T.monst | null} mon struct monst *
 * @param {number | bigint} amount long
 * @returns {Promise<number | bigint>} long
 */
export async function money2mon(mon, amount) {   // shk.c:157
    let ygold = null;
    ygold = findgold(gi.invent);
    if (amount <= 0) {
        await impossible($c.lit("%s payment in money2mon!"), amount ? $c.lit("negative") : $c.lit("zero"));
        return 0;
    }
    if (!ygold || ygold.quan < amount) {
        await impossible($c.lit("Paying without %s gold?"), ygold ? $c.lit("enough") : $c.lit(""));
        return 0;
    }
    if (ygold.quan > amount) {
        ygold = await splitobj(ygold, amount);
    } else if (ygold.owornmask) {
        await remove_worn_item(ygold, FALSE);   /* quiver */
    }
    await freeinv(ygold);
    await add_to_minv(mon, ygold);
    disp.botl = TRUE;
    return amount;
}
